from html.parser import HTMLParser

VOID = {'meta','br','img','hr','input','link'}
class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in VOID:
