from html.parser import HTMLParser
import re

VOID = {'meta','br','img','hr','input','link'}
class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in VOID:
            self.stack.append((tag, self.getpos()))
    def handle_endtag(self, tag):
        if not self.stack:
            self.errors.append(f"Unexpected </{tag}> at {self.getpos()}"); return
        open_tag, pos = self.stack.pop()
        if open_tag != tag:
            self.errors.append(f"Mismatch: <{open_tag}> at {pos} closed by </{tag}> at {self.getpos()}")

html = open('/home/agent/workspace/index.html', encoding='utf-8').read()
